def _s_first_magic(scope, key, _t):
    if key in scope:
        return scope[key]
    raise PathAccessError(KeyError(key), Path(key), 0)


def _t_eval(target, _t, scope):
    t_ops = _t.__ops__
    root = t_ops[0]

    if root is S:
        return _s_first_magic(scope, t_ops[2], _t)
    elif root is A:
        if len(t_ops) == 1:
            return target
        new_t = TType()
        new_t.__ops__ = (T,) + t_ops[1:]
        return _t_eval(target, new_t, scope)

    i = 1
    while i < len(t_ops):
        op, arg = t_ops[i], t_ops[i + 1]
        i += 2

        if op == '.':
            try:
                target = getattr(target, arg)
            except AttributeError as e:
                raise PathAccessError(e, Path(*scope[Path] + [arg]), len(scope[Path]))
        elif op == '[':
            try:
                target = target[arg]
            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(*scope[Path] + [arg]), len(scope[Path]))
        elif op == 'P':
            get = scope[TargetRegistry].get_handler('get', target, path=scope[Path])
            try:
                target = get(target, arg)
            except (KeyError, IndexError, AttributeError, TypeError) as e:
                raise PathAccessError(e, Path(*scope[Path] + [arg]), len(scope[Path]))
        elif op == '(':
            args, kwargs = arg
            args = arg_val(target, args, scope)
            kwargs = arg_val(target, kwargs, scope)
            target = target(*args, **kwargs)
        elif op == 'x':
            iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
            try:
                target = list(iterate(target))
            except Exception as e:
                raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                                % (target.__class__.__name__, Path(*scope[Path]), e))
        elif op == 'X':
            def _recursive_descent(obj, get_handler):
                children = [obj]
                _extend_children(children, obj, get_handler)
                for child in children:
                    _extend_children(children, child, get_handler)
                return children

            get_handler = scope[TargetRegistry].get_handler
            target = _recursive_descent(target, get_handler)
        elif op == '+':
            arg_val_result = arg_val(target, arg, scope)
            target = target + arg_val_result
        elif op == '-':
            arg_val_result = arg_val(target, arg, scope)
            target = target - arg_val_result
        elif op == '*':
            arg_val_result = arg_val(target, arg, scope)
            target = target * arg_val_result
        elif op == '/':
            arg_val_result = arg_val(target, arg, scope)
            try:
                target = target / arg_val_result
            except ZeroDivisionError as e:
                raise PathAccessError(e, Path(*scope[Path]), len(scope[Path]))
        elif op == '#':
            arg_val_result = arg_val(target, arg, scope)
            target = target // arg_val_result
        elif op == '%':
            arg_val_result = arg_val(target, arg, scope)
            target = target % arg_val_result
        elif op == ':':
            arg_val_result = arg_val(target, arg, scope)
            target = target ** arg_val_result
        elif op == '&':
            arg_val_result = arg_val(target, arg, scope)
            target = target & arg_val_result
        elif op == '|':
            arg_val_result = arg_val(target, arg, scope)
            target = target | arg_val_result
        elif op == '^':
            arg_val_result = arg_val(target, arg, scope)
            target = target ^ arg_val_result
        elif op == '~':
            target = ~target
        elif op == '_':
            target = -target

    return target


def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', None)
    if scope is None:
        scope = _DEFAULT_SCOPE
    elif not isinstance(scope, ChainMap):
        scope = ChainMap(scope)

    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', GlomError)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)

    if kwargs:
        raise TypeError(f'unexpected keyword arguments: {sorted(kwargs.keys())!r}')

    scope = scope.new_child({
        Path: [],
        MODE: AUTO,
        MIN_MODE: None,
        glom: _glom,
        TargetRegistry: scope[TargetRegistry],
    })

    try:
        return _glom(target, spec, scope)
    except skip_exc as e:
        if default is not _MISSING:
            return arg_val(target, default, scope)
        if glom_debug:
            raise
        err = GlomError.wrap(e) if not isinstance(e, GlomError) else e
        err._finalize(scope)
        raise err
    except GlomError as e:
        if glom_debug:
            raise
        e._finalize(scope)
        raise
